INSERT INTO public.website_squads (slug, name, title, hero_img, photo, intro, league_url, roster, published, sort_order) VALUES
('u19', 'U19 Squad', 'Under 19 Playing Squad', '/summer/DJI_20240719121925_0067_D-scaled.jpg', '/teams/IFG-U19-scaled.jpg', '["Introducing the dedicated and passionate players who make up our formidable Under-19 football squad! These young athletes have demonstrated an unwavering commitment to their sport, putting in countless hours of hard work, dedication, and teamwork to earn their place in this elite team.", "Their talent and determination are second to none, and they are ready to bring their A-game to every match. With a shared love for the beautiful game and a strong sense of camaraderie, these players are not just teammates; they are a family — poised to tackle any challenge that comes their way and showcase their skills on the field with pride and determination.", "Get ready to witness the future of football as these remarkable Under-19 players light up the pitch!"]'::jsonb, 'https://fulltime.thefa.com/displayTeam.html?divisionseason=946824025&teamID=517437792', '[{"name": "Matt Delk", "pos": "GK"}, {"name": "Nicholas Mercado", "pos": "GK"}, {"name": "Daniel Gutierrez", "pos": "GK"}, {"name": "Thiago Carvalho", "pos": "RB"}, {"name": "Mario Campbell", "pos": "RB"}, {"name": "Efosa ''Elvis'' Ogbeide", "pos": "CB"}, {"name": "Ian Coward", "pos": "CB"}, {"name": "Nick Swift", "pos": "CB"}, {"name": "Telmo Carvalho", "pos": "LB"}, {"name": "George Lara", "pos": "CDM"}, {"name": "Joahan Ponce", "pos": "CDM"}, {"name": "Emmet Ritchie", "pos": "CDM"}, {"name": "Nery Rios", "pos": "CM"}, {"name": "Jesse Palacios", "pos": "CM"}, {"name": "Mor Talla Seck", "pos": "CM"}, {"name": "Elliot Prince", "pos": "Winger"}, {"name": "Fernando Ojeda", "pos": "Winger"}, {"name": "Evan Lozano", "pos": "Winger"}, {"name": "Devin Snyder", "pos": "Winger"}, {"name": "Cameron Daly", "pos": "ST"}]'::jsonb, true, 0),
('u20', 'U20 Squad', 'Under 20 Playing Squad', '/summer/DJI_20240719121925_0067_D-scaled.jpg', '/teams/IFG-U20-scaled.jpg', '["Introducing the dedicated and passionate players who form the core of our formidable Under-20 football squad! These rising stars have shown an unwavering commitment to their sport, dedicating countless hours to hard work, discipline, and teamwork to secure their positions in this esteemed team.", "Their exceptional talent and unwavering determination set them apart, and they''re fully prepared to deliver their absolute best in every match. With a shared passion for the beautiful game and a deep sense of camaraderie, these players are not just teammates; they are a tightly-knit family — ready to face any challenge that crosses their path and proudly display their skills on the field.", "Prepare to witness the future of football as these remarkable Under-20 players light up the pitch!"]'::jsonb, NULL, '[]'::jsonb, true, 1),
('u21', 'U21 Squad', 'Under 21 Playing Squad', '/summer/DJI_20240719121925_0067_D-scaled.jpg', '/teams/u21.jpg', '["Allow us to introduce the dedicated and passionate athletes who compose our formidable Under-21 team! These talented individuals have exhibited an unwavering devotion to their sport, investing countless hours in rigorous training, unwavering commitment, and a united spirit to earn their spots on this prestigious team.", "Their extraordinary skills and resolute determination set them apart, and they are prepared to bring their absolute best to every match. With a shared passion for the beautiful game and a deep bond of camaraderie, these players are more than just teammates; they are a tight-knit family — well-equipped to conquer any challenge that arises and to proudly exhibit their abilities on the field.", "Get ready to witness the future of football as these remarkable Under-21 players shine on the pitch!"]'::jsonb, NULL, '[{"name": "Jonathon Thornton", "pos": "GK"}, {"name": "Matthew Jones Parkinson", "pos": "GK"}, {"name": "Andres Martinez", "pos": "GK"}, {"name": "Thaddeus Harp", "pos": "RB"}, {"name": "Taylor Plourde", "pos": "RB"}, {"name": "Zach Martinez", "pos": "CB"}, {"name": "Luke Price", "pos": "CB"}, {"name": "Cody Williams", "pos": "CB"}, {"name": "Gabriel Lucero", "pos": "CB"}, {"name": "Grant Jennings", "pos": "CB"}, {"name": "Will Prince", "pos": "LB"}, {"name": "Dameon Phillippi", "pos": "CM"}, {"name": "John Alex Hoopes", "pos": "CM"}, {"name": "Jelle Siebring", "pos": "CM"}, {"name": "Erwan Friche", "pos": "CM"}, {"name": "Luke Draysey", "pos": "CM"}, {"name": "Ryan Russell", "pos": "Winger"}, {"name": "Paul Hyatt", "pos": "Winger"}, {"name": "Mason Brown", "pos": "Winger"}, {"name": "Salvatore Zannone", "pos": "ST"}]'::jsonb, true, 2),
